<?php
namespace App\Http\Controllers; use App\Models\{LetterRequest,PracticumClass,TestingRequest,User}; use Illuminate\Http\Request; class HeadLabController extends Controller { public function dashboard(Request $r){ $labId=$r->user()->laboratory_id; $classes=PracticumClass::with('course')->withCount(['finalRegistrations'=>fn($q)=>$q->where('status','approved')])->where('laboratory_id',$labId)->get(); $tests=TestingRequest::with(['applicant','service'])->whereHas('service',fn($q)=>$q->where('laboratory_id',$labId))->latest()->limit(10)->get(); $letters=LetterRequest::with(['letterType','applicant'])->where('laboratory_id',$labId)->latest()->limit(10)->get(); $staffCount=User::where('laboratory_id',$labId)->where('role','tenaga_labor')->count(); return view('kepala_labor.dashboard',compact('classes','tests','letters','staffCount')); } }
